import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import datetime
import os

# Create output dir
os.makedirs('/app/output', exist_ok=True)

# 1. Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])
df['year'] = df['date'].dt.year
df['month'] = df['date'].dt.month
df['month_name'] = df['date'].dt.month_name()
df['day_of_week'] = df['date'].dt.day_name()
df['is_workout'] = df['workout_type'] != 'None'

# Set style
plt.style.use('seaborn-v0_8-whitegrid')
sns.set_palette("husl")

def get_base64_image(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    img_base64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{img_base64}"

# --- Calculate KPIs & Stats ---
total_records = len(df)
unique_users = df['user_id'].nunique()
avg_daily_steps = df['steps'].mean()
avg_calories = df['calories_burned'].mean()
avg_sleep = df['sleep_hours'].mean()
workout_participation = (df['is_workout'].sum() / total_records) * 100
avg_stress = df['stress_level'].mean()

# Segmented stats
steps_by_gender = df.groupby('gender')['steps'].mean().to_dict()
steps_by_workout = df.groupby('workout_type')['steps'].mean().to_dict()
steps_by_mood = df.groupby('mood')['steps'].mean().to_dict()
calories_by_workout = df.groupby('workout_type')['calories_burned'].mean().to_dict()
sleep_by_mood = df.groupby('mood')['sleep_hours'].mean().to_dict()
stress_by_mood = df.groupby('mood')['stress_level'].mean().to_dict()

# Identify highest/lowest months
monthly_steps = df.groupby('month_name')['steps'].mean()
best_month = monthly_steps.idxmax()
worst_month = monthly_steps.idxmin()

# Identify highest activity mood
best_mood_steps = max(steps_by_mood, key=steps_by_mood.get)

# --- Generate Charts ---
charts = {}

# 1. Temporal Trends & Seasonal Patterns (HIGHEST PRIORITY)
fig, ax1 = plt.subplots(figsize=(10, 5))
yearly_stats = df.groupby('year').agg({'steps': 'mean', 'is_workout': 'mean'}).reset_index()
ax1.plot(yearly_stats['year'], yearly_stats['steps'], marker='o', color='#2980b9', linewidth=2, label='Avg Steps')
ax1.set_xlabel('Year', fontsize=12)
ax1.set_ylabel('Average Daily Steps', color='#2980b9', fontsize=12)
ax1.tick_params(axis='y', labelcolor='#2980b9')
ax1.set_xticks(yearly_stats['year'].unique())

ax2 = ax1.twinx()
ax2.plot(yearly_stats['year'], yearly_stats['is_workout']*100, marker='s', color='#c0392b', linewidth=2, label='Workout Rate (%)')
ax2.set_ylabel('Workout Participation Rate (%)', color='#c0392b', fontsize=12)
ax2.tick_params(axis='y', labelcolor='#c0392b')
plt.title('Year-over-Year Trend: Steps and Workout Participation', fontsize=14, pad=15)
charts['yoy_trend'] = get_base64_image(fig)

fig, ax = plt.subplots(figsize=(10, 5))
monthly_order = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
monthly_stats = df.groupby('month_name')['steps'].mean().reindex(monthly_order).reset_index()
sns.barplot(x='month_name', y='steps', data=monthly_stats, ax=ax, palette='viridis')
ax.set_title('Average Daily Steps by Month (Seasonality)', fontsize=14, pad=15)
ax.set_xlabel('Month')
ax.set_ylabel('Average Steps')
plt.xticks(rotation=45)
charts['monthly_seasonality'] = get_base64_image(fig)

# 2. Demographics
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))
sns.histplot(df['age'], bins=15, kde=True, ax=ax1, color='#3498db')
ax1.set_title('Age Distribution')
ax1.set_xlabel('Age')
gender_counts = df['gender'].value_counts()
ax2.pie(gender_counts, labels=gender_counts.index, autopct='%1.1f%%', colors=['#ff9999','#66b3ff'], startangle=90)
ax2.set_title('Gender Distribution')
charts['demographics'] = get_base64_image(fig)

# 3. Activity Patterns
fig, ax = plt.subplots(figsize=(10, 5))
sns.boxplot(x='workout_type', y='steps', data=df, ax=ax, palette='Set2')
ax.set_title('Daily Steps Distribution by Workout Type')
ax.set_xlabel('Workout Type')
ax.set_ylabel('Daily Steps')
charts['activity_workout'] = get_base64_image(fig)

# 4. Health Vitals
fig, ax = plt.subplots(figsize=(10, 5))
sns.scatterplot(x='workout_duration_minutes', y='calories_burned', hue='workout_type', data=df[df['is_workout']], ax=ax, alpha=0.7)
ax.set_title('Calories Burned vs Workout Duration (Active Days)')
ax.set_xlabel('Workout Duration (Minutes)')
ax.set_ylabel('Calories Burned')
charts['vitals_calories'] = get_base64_image(fig)

# 5. Lifestyle Indicators
fig, ax = plt.subplots(figsize=(10, 5))
sns.barplot(x='mood', y='stress_level', data=df, ax=ax, palette='coolwarm')
ax.set_title('Average Stress Level by Mood')
ax.set_xlabel('Self-Reported Mood')
ax.set_ylabel('Average Stress Level (Scale 1-10)')
charts['lifestyle_stress'] = get_base64_image(fig)

# --- Generate Dynamic HTML ---
html_template = f"""
