        }}
        .header-section {{
            border-bottom: 3px solid #2563eb;
            padding-bottom: 20px;
            margin-bottom: 30px;
        }}
        h1 {{
            color: #1e293b;
            margin-bottom: 10px;
            font-size: 2.2em;
        }}
        h2 {{
            color: #0f172a;
