            text-align: center;
        }}
        .kpi-value {{
            font-size: 2.2em;
            font-weight: 700;
            color: #1e40af;
            margin: 10px 0;
        }}
        .kpi-label {{
            font-size: 0.85em;
            color: #64748b;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            font-weight: 600;
        }}
        .chart-row {{
            display: flex;
            flex-wrap: wrap;
            gap: 20px;
            margin-bottom: 30px;
        }}
